files.content:
* { box-sizing: border-box; }
[hidden] { display: none !important; }

body {
  margin: 0;
  min-height: 100vh;
  display: grid;
  place-items: center;
  background: #1a1c2c;
  color: #f4f4f4;
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 18px;
  line-height: 1.5;
  padding: 16px;
}

.card {
  width: min(100%, 420px);
  background: #29366f;
  border: 4px solid #f4f4f4;
  border-radius: 0;
  box-shadow: 8px 8px 0 #000;
  padding: 28px 24px;
  text-align: center;
}

h1 {
  margin: 0 0 16px;
  font-size: 1.6rem;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: #ffcd75;
}

#question {
  margin: 0 0 24px;
  font-size: 1.8rem;
  font-weight: 700;
  min-height: 2.4em;
  display: flex;
  align-items: center;
  justify-content: center;
}

.answers {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
  margin-bottom: 20px;
}

button {
  font: inherit;
  font-weight: 700;
  color: #1a1c2c;
  background: #f4f4f4;
  border: 3px solid #1a1c2c;
  border-radius: 0;
  padding: 14px 12px;
  cursor: pointer;
  box-shadow: 4px 4px 0 #000;
  transition: transform 0.05s, box-shadow 0.05s, background 0.15s;
}

button:hover:not(:disabled) { background: #ffcd75; }
button:focus-visible { outline: 3px solid #ffcd75; outline-offset: 3px; }
button:active:not(:disabled) { transform: translate(3px, 3px); box-shadow: 1px 1px 0 #000; }
button:disabled { opacity: 0.55; cursor: not-allowed; box-shadow: none; transform: none; }

.score-line {
  margin: 0 0 20px;
  font-size: 1.1rem;
  color: #a7f070;
}

.controls {
  display: flex;
  gap: 12px;
  justify-content: center;
  flex-wrap: wrap;
}

.controls button { flex: 1 1 120px; }

@media (max-width: 380px) {
  .card { padding: 20px 14px; }
  #question { font-size: 1.5rem; }
  .answers { gap: 10px; }
  button { padding: 12px 8px; }
}

const questionEl = document.getElementById('question');
const answerA = document.getElementById('answer-a');
const answerB = document.getElementById('answer-b');
const scoreEl = document.getElementById('score');
const nextBtn = document.getElementById('next');
const restartBtn = document.getElementById('restart');

const questions = [
  { text: '2 + 2 = ?', a: '4', b: '5', correct: 'a' },
  { text: '3 + 3 = ?', a: '5', b: '6', correct: 'b' }
];

let index = 0;
let score = 0;
let locked = false;
let finished = false;

function render() {
  const q = questions[index];
  questionEl.textContent = q.text;
  answerA.textContent = q.a;
  answerB.textContent = q.b;
  answerA.disabled = false;
  answerB.disabled = false;
  locked = false;
  finished = false;
  nextBtn.disabled = false;
}

function answer(choice) {
  if (locked || finished) return;
  locked = true;
  answerA.disabled = true;
  answerB.disabled = true;
  if (choice === questions[index].correct) {
    score += 1;
    scoreEl.textContent = String(score);
  }
}

answerA.addEventListener('click', () => answer('a'));
answerB.addEventListener('click', () => answer('b'));

nextBtn.addEventListener('click', () => {
  if (finished) return;
  if (!locked) return;
  if (index === 0) {
    index = 1;
    render();
  } else {
    finished = true;
    locked = true;
    questionEl.textContent = 'Finished';
    answerA.disabled = true;
    answerB.disabled = true;
    nextBtn.disabled = true;
  }
});

restartBtn.addEventListener('click', () => {
  index = 0;
  score = 0;
  scoreEl.textContent = '0';
  render();
});

render();
